<script setup lang="ts">
import type { Tool } from '../../../shared/types'
const route=useRoute()
const slug=computed(()=>String(route.params.slug))
const {data}=await useFetch<{tools:Tool[]}>('/api/tools')
const tool=computed(()=>data.value?.tools?.find(t=>t.slug===slug.value))
const payload=reactive<Record<string,any>>({content:'',mode:'pretty',indent:2,target:'client',tone:'professional',customer:'',subject:'',analysis:'',action:'',next:'',preset:'windows-network',host:'localhost',port:3050,service:'FirebirdServerDefaultInstance',category:'incident',description:'',title:'',context:'',steps:'',result:''})
const output=ref(''),message=ref(''),error=ref(''),busy=ref(false)
const fields:Record<string,Array<{key:string;label:string;type?:string;options?:Array<[string,string]>;required?:boolean}>>={
  'xml-validator':[{key:'content',label:'Conteúdo XML',type:'textarea',required:true}],
  'json-formatter':[{key:'content',label:'Cole seu JSON',type:'textarea',required:true},{key:'mode',label:'Modo de formatação',options:[['pretty','Formatado'],['compact','Compacto']]}],
  'feedback-generator':[{key:'target',label:'Destinatário',options:[['client','Cliente'],['internal','Interno'],['escalation','Encaminhamento']]},{key:'tone',label:'Tom',options:[['professional','Profissional'],['direct','Direto']]},{key:'customer',label:'Nome do cliente'},{key:'subject',label:'Assunto',required:true},{key:'analysis',label:'Análise',type:'textarea',required:true},{key:'action',label:'Ações realizadas',type:'textarea',required:true},{key:'next',label:'Próximos passos',type:'textarea'}],
  'script-generator':[{key:'preset',label:'Modelo',options:[['windows-network','Rede / CMD'],['windows-services','Serviços do Windows'],['powershell-port','Teste de porta / PowerShell'],['sql-read','SQL de leitura']]},{key:'host',label:'Host / IP'},{key:'port',label:'Porta',type:'number'},{key:'service',label:'Serviço do Windows'}],
  'scope-checker':[{key:'category',label:'Tipo de demanda',options:[['installation','Instalação'],['incident','Incidente'],['fiscal','Fiscal'],['customization','Personalização'],['access','Acesso']]},{key:'description',label:'Descrição da demanda',type:'textarea',required:true}],
  'share-builder':[{key:'title',label:'Título',required:true},{key:'context',label:'Contexto',type:'textarea',required:true},{key:'steps',label:'Passo a passo',type:'textarea',required:true},{key:'result',label:'Resultado / observações',type:'textarea'}],
  'text-utilities':[{key:'action',label:'Ação',options:[['trim','Limpar linhas'],['unique','Remover duplicados'],['stats','Estatísticas']]},{key:'content',label:'Cole o texto',type:'textarea',required:true}]
}
const formFields=computed(()=>fields[slug.value] || [])
async function execute(){busy.value=true;error.value='';output.value='';message.value='';try {const data=await $fetch<{result:{title:string;output:string;note?:string}}>(`/api/tools/${slug.value}/execute`,{method:'POST',body:{...payload}});output.value=data.result.output;message.value=data.result.note||data.result.title}catch(e){error.value=apiMessage(e)}finally{busy.value=false}}
async function copy(){if(!output.value)return;try{await navigator.clipboard.writeText(output.value);message.value='Resultado copiado.'}catch{message.value='Selecione o conteúdo e copie manualmente.'}}
</script>
<template><div class="container page"><NuxtLink to="/tools" class="inline-link">← Voltar às Webee Tools</NuxtLink><div v-if="tool" style="margin-top:28px"><header class="page-heading"><div class="eyebrow">{{tool.category}}</div><h1>{{tool.name}}</h1><p>{{tool.description}}</p></header><div v-if="slug==='releases'" class="panel panel-pad"><NuxtLink class="btn btn-primary" to="/releases">Consultar releases</NuxtLink></div><div v-else class="two-columns"><div class="panel panel-pad"><h2 style="font-size:19px">Configurar ferramenta</h2><form @submit.prevent="execute" class="form-grid"><div v-for="f in formFields" :key="f.key" class="field full"><label :for="f.key">{{f.label}}</label><select v-if="f.options" :id="f.key" v-model="payload[f.key]"><option v-for="[value,label] in f.options" :key="value" :value="value">{{label}}</option></select><textarea v-else-if="f.type==='textarea'" :id="f.key" v-model="payload[f.key]" rows="5" :required="f.required" :placeholder="f.label"/><input v-else :id="f.key" v-model="payload[f.key]" :type="f.type||'text'" :required="f.required" :placeholder="f.label"></div><div class="full"><div v-if="error" class="error" role="alert">{{error}}</div><button class="btn btn-primary" type="submit" :disabled="busy">{{busy?'Processando...':'Executar ferramenta →'}}</button></div></form></div><div class="panel panel-pad"><div class="editor-heading"><h2>Resultado</h2><button v-if="output" class="btn btn-small btn-outline" @click="copy">Copiar</button></div><div v-if="output"><div class="viewer">{{output}}</div><p class="form-help" style="margin-top:12px">{{message}}</p></div><div v-else class="empty"><span class="empty-icon">⌘</span>Preencha os campos ao lado para visualizar o resultado.</div></div></div></div><div v-else class="empty" style="margin-top:30px">Ferramenta não encontrada.</div></div></template>
